// Принимает outbox event {event_id, event_type, data:{to,to_name,token,base_url}}
// и собирает payload для UniSender Go /email/send.json.
// Поддержка: email.verify_send, email.password_reset_send.
const raw = $input.first().json;
const e = raw.body || raw;
const t = e.event_type;
const d = e.data || {};

// ⚠️ Заменить на реальный from в n8n UI (Code node → правка константы).
// Хранить в env-vars из n8n task runner запрещено (см. enrichProjectPayload
// в API — там та же причина). Для прода — отдельный workflow на каждое окружение.
const FROM_EMAIL = 'noreply@marketpclce.com';
const FROM_NAME  = 'Marketpclce';

const to     = d.to || '';
const toName = d.to_name || '';
const token  = d.token || '';
const base   = (d.base_url || '').replace(/\/$/,'');

let subject, plain, html;
switch (t) {
  case 'email.verify_send': {
    const link = `${base}/verify?token=${encodeURIComponent(token)}`;
    subject = 'Подтвердите email';
    plain = `Здравствуйте${toName?', '+toName:''}!\n\nПодтвердите свой email перейдя по ссылке:\n${link}\n\nСсылка действительна 24 часа.\n\n— Marketpclce`;
    html  = `<p>Здравствуйте${toName?', '+toName:''}!</p>` +
            `<p>Подтвердите свой email:</p>` +
            `<p><a href="${link}">Подтвердить</a></p>` +
            `<p>Если кнопка не работает — скопируйте ссылку: <br>${link}</p>` +
            `<p>Ссылка действительна 24 часа.</p>` +
            `<p>— Marketpclce</p>`;
    break;
  }
  case 'email.password_reset_send': {
    const link = `${base}/auth/reset?token=${encodeURIComponent(token)}`;
    subject = 'Сброс пароля';
    plain = `Здравствуйте${toName?', '+toName:''}!\n\nДля сброса пароля перейдите по ссылке:\n${link}\n\nЕсли вы не запрашивали сброс — проигнорируйте это письмо.\n\n— Marketpclce`;
    html  = `<p>Здравствуйте${toName?', '+toName:''}!</p>` +
            `<p>Для сброса пароля:</p>` +
            `<p><a href="${link}">Сбросить пароль</a></p>` +
            `<p>Если кнопка не работает — скопируйте ссылку: <br>${link}</p>` +
            `<p>Если вы не запрашивали сброс — проигнорируйте это письмо.</p>` +
            `<p>— Marketpclce</p>`;
    break;
  }
  default:
    return [];
}

return [{ json: {
  message: {
    recipients: [{ email: to, substitutions: toName ? { to_name: toName } : {} }],
    subject,
    body: { plaintext: plain, html },
    from_email: FROM_EMAIL,
    from_name:  FROM_NAME,
  }
}}];
